#![allow(unused_imports)]
use verus::prelude::*;

// Define the kinds of dtypes.
#[verus::spec]
#[derive(PartialEq, Eq)]
pub enum Kind {
    BoolKind,
    SignedInt,
    UnsignedInt,
    FloatKind,
    ComplexKind,
    ObjectKind,
}

// Define the NumPy‐like data types.
#[verus::spec]
#[derive(PartialEq, Eq)]
pub enum DType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    Float32,
    Float64,
    Complex64,
    Complex128,
    Object,
}

impl DType {
    // Precedence for promotion: larger means more general
    #[verus::spec]
    pub fn precedence(self) -> nat {
        match self {
            DType::Bool        => 0,
            DType::Int8        => 1,
            DType::Int16       => 2,
            DType::Int32       => 3,
            DType::Int64       => 4,
            DType::UInt8       => 5,
            DType::UInt16      => 6,
            DType::UInt32      => 7,
            DType::UInt64      => 8,
            DType::Float32     => 9,
            DType::Float64     => 10,
            DType::Complex64   => 11,
            DType::Complex128  => 12,
            DType::Object      => 13,
        }
    }

    // Kind/category of the dtype
    #[verus::spec]
    pub fn kind(self) -> Kind {
        match self {
            DType::Bool        => Kind::BoolKind,
            DType::Int8
            | DType::Int16
            | DType::Int32
            | DType::Int64     => Kind::SignedInt,
            DType::UInt8
            | DType::UInt16
            | DType::UInt32
            | DType::UInt64    => Kind::UnsignedInt,
            DType::Float32
            | DType::Float64   => Kind::FloatKind,
            DType::Complex64
            | DType::Complex128=> Kind::ComplexKind,
            DType::Object      => Kind::ObjectKind,
        }
    }
}

